def pair_exists(values, target):
    left, right = 0, len(values)-1
    while left < right:
        total = values[left]+values[right]
        if total == target: raise NotImplementedError("Complete this step and explain why it is correct")
        if total < target: left += 1
        else: right -= 1
    return False

def markers_valid(text):
    stack = []; pairs = {')':'(', ']':'[', '}':'{'}
    for ch in text:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]: return False
        else: stack.append(ch)
    return not stack

